    if (!rows || rows.length === 0)
        return result + "\t".repeat(indent) + "\\end{table}";
    // 确定列数
    let columnCount = 0;
    for (const row of rows) {
        if (row.type === 'tableRow' && row.children) {
            columnCount = Math.max(columnCount, row.children.length);
        }
    }
    // 创建列格式
