    parseBibtex(text) {
        const items = [...text.matchAll(bibItemPattern)].map(i => i[2]);
        const kvps = items.map(i => [i.match(bibKeyPattern)[1], i]);
        const result = Object.fromEntries(kvps);
        return result;
    }
